#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define BALLCOUNT 20
#define COPYCOUNT 20

float roundrect(vec2 uv, vec2 pos, vec2 dim){
    vec2 r = abs(uv - pos) - dim;
    return max(r.x, r.y);
}

float disk(vec2 uv, vec2 pos, float radius){
    return length(uv - pos) - radius;
}

float PingPongTime(float time, float deform){
    int t = int(floor(time));
    float res = (t % 2 == 0) ? fract(time) : 1.0 - fract(time);
    return pow(res, deform);
}

uint murmurHash3(uint h) {
	h ^= h >> 16;
	h *= uint(0x85ebca6b);
	h ^= h >> 13;
	h *= uint(0xc2b2ae3d);
	h ^= h >> 16;
	return h;
}

float random(uint state){
    return float(murmurHash3(state)) / 4294967295.0;
}

vec3 randomColor(uint state){
    float randHue = random(state);
    vec3 rgb = clamp( abs(mod(randHue*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
    return rgb;
}
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}
float remap(float In, vec2 InMinMax, vec2 OutMinMax)
{
    return (OutMinMax.x + (In - InMinMax.x) * (OutMinMax.y - OutMinMax.x) / (InMinMax.y - InMinMax.x));
}
