            float ballYPos = remap(YTime, vec2(0.0, 1.0), vec2(ballRadius, 1.0 - ballRadius));

            vec3 ballColor = randomColor(uint(i * 20 + 5884));

            float sdf = disk(uv, vec2(ballXPos, ballYPos), ballRadius * pow(float(j) / float(COPYCOUNT-1), 2.0));
            finalColor = mix(ballColor, finalColor, smoothstep(-0.005, 0.0, sdf));
        }
    }
        float audio = texture(iChannel0, vec2(0.03, C.y / r.y)).r;
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(0.1,0.2,1.),H(g*.1),.8)*1./e/8e3
    )
    {
        p=g*d;
    p.z+=cos(iTime)*2.;
        a=30.;
        p=mod(p-a,a*2.)-a;
        s=3.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.z+=cos(iTime)*2.
            ;
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+(1.511)+audio*.1;
            p=abs(p)*e-
                vec3(
                    15.*3.,
                    120,
                    10.*5.
                 )+finalColor;
         }
         g+=e=length(p.yz)/s;
    }
        float anim = sin(iTime * 12.0) * 0.1 + 1.0;  // anim between 0.9 - 1.1 
      O*= vec4(happy_star(uv3, anim) * vec3(0.35,0.2,0.15)*2.2, 1.0);
       O*=vec4(happy_star(uv4,anim) * vec3(0.35,0.2,0.15)*2.5, 1.0);
       O-=vec4(finalColor,1.);

}
